 list.addEventListener('pointerdown',e=>{if(e.target.closest('[role=option]'))e.preventDefault();});function removeHistory(i){const option=options[i];if(!option?.history)return;history=history.filter(h=>!(norm(h.q)===norm(option.q)&&h.kind===option.kind&&h.provider===option.provider));saveHistory();paint();live.textContent='Recent search deleted.';}
